import hashlib, json
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urlsplit, parse_qs

class IntakeLinks(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []

    def handle_starttag(self, tag, attrs):
        href = dict(attrs).get('href', '') or ''
        if tag == 'a' and href.startswith('mailto:'):
            url = urlsplit(href)
            params = parse_qs(url.query)
            self.links.append({'recipient_sha256': hashlib.sha256(url.path.encode()).hexdigest(), 'subject': params.get('subject', []), 'body': params.get('body', [])})

base = Path('products/services/sqlite-repair/bespoke-inbound/quote-intake-preview')

def read_page(path):
    if not path.is_file():
        return {'state': 'CAPTURE_MISSING'}
    raw = path.read_bytes()
    parser = IntakeLinks()
    parser.feed(raw.decode('utf-8'))
    return {'state': 'READ', 'sha256': hashlib.sha256(raw).hexdigest(), 'intake_links': parser.links}

live = read_page(base / 'current-live-readback.html')
candidate = read_page(Path('products/sites/sqlite-statement-diagnostic/index.html'))
both_read = live['state'] == candidate['state'] == 'READ'
report = {'live': live, 'candidate': candidate, 'homepage_bytes_match': live['sha256'] == candidate['sha256'] if both_read else None, 'decoded_intake_links_match': live['intake_links'] == candidate['intake_links'] if both_read else None, 'scope': 'Public homepage bytes and decoded mailto fields only. This check supplies no approval, email delivery or commercial outcome evidence.'}
base.mkdir(parents=True, exist_ok=True)
(base / 'current-release-comparison.json').write_text(json.dumps(report, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(json.dumps({key: report[key] for key in ('homepage_bytes_match', 'decoded_intake_links_match')}))
